        .binding-rings {
            position: absolute;
            left: 0;
            top: 0;
            bottom: 0;
            width: 40px;
            background-image: 
                radial-gradient(circle at 20px 25px, #d0d0d0 8px, transparent 9px),
                linear-gradient(to right, transparent 10px, #a0a0a0 11px, #a0a0a0 25px, transparent 26px);
            background-size: 100% 40px, 100% 100%;
