        .title-diamond { color: #f2c75a; font-size: 1.2em; vertical-align: middle; margin: 0 5px; }

        /* Unit Sections */
        .unit-section {
            margin-bottom: 25px;
            padding-right: 20px;
        }

        .unit-heading-wrapper {
            text-align: center;
            margin-bottom: 15px;
        }

        .unit-heading {
            display: inline-block;
            background-color: #fbecec;
            border: 1px solid #555;
            padding: 4px 25px;
            font-size: 18px;
            font-weight: bold;
            color: #cc3333;
            border-radius: 5px;
            position: relative;
        }

        .unit-heading .star { color: #f2c75a; }
        .unit-heading .heart { color: #cc3333; }

        /* Vocabulary Table Grid */
        table {
            width: 100%;
            border-collapse: collapse;
            table-layout: fixed;
        }

        td {
            padding: 8px 5px;
            vertical-align: middle;
        }

        /* Simulating notebook lines */
        tr {
            border-bottom: 1px dashed #c0c0c0;
        }
        .unit-section table tr:last-child {
            border-bottom: none; /* Let the next section handle spacing */
        }

        .col-category {
            width: 85px;
            text-align: right;
            padding-right: 15px;
            font-size: 15px;
            color: #222;
            vertical-align: top;
            padding-top: 15px;
        }

        .col-vocab {
            width: 21%;
