        .vocab-item {
            display: inline-flex;
            align-items: flex-end;
        }

        .text-group {
            display: inline-block;
            border-bottom: 2px solid #88ced4; /* Default underline */
            padding-bottom: 2px;
            white-space: nowrap;
        }

        .word-eng {
            color: #a32a24; /* Dark red */
